import{_ as e,o as s,c as r,a2 as a}from"./chunks/framework.ChIlRNAd.js";const p=JSON.parse('{"title":"Activité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/activity.md","filePath":"fr/guide/activity.md"}'),n={name:"fr/guide/activity.md"};function o(i,t,l,d,c,u){return s(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="activite" tabindex="-1">Activité <a class="header-anchor" href="#activite" aria-label="Permalink to &quot;Activité&quot;">​</a></h1><p>La page <strong>Activité</strong> (<code>/activity</code>) liste « tout ce que vous et vos règles avez lancé, en direct » : actions de masse, sauvegardes NAS, règles, analyses, imports, purges… Elle remplace l&#39;ancienne page « Suivi des jobs ».</p><p>Sur ordinateur, la barre latérale affiche « N en cours » à côté d&#39;<strong>Activité</strong> ; sur mobile, la page est dans <strong>Plus › Outils</strong>.</p><hr><h2 id="filtres" tabindex="-1">Filtres <a class="header-anchor" href="#filtres" aria-label="Permalink to &quot;Filtres&quot;">​</a></h2><ul><li><strong>Compte Gmail</strong> : un compte ou <strong>Tous les comptes</strong>. Les tâches propres à l&#39;instance (sans compte) sont marquées <strong>Instance</strong>.</li><li><strong>Statut</strong>, en puces avec compteur : <strong>Toutes</strong>, <strong>En attente</strong>, <strong>En cours</strong>, <strong>Échouées</strong>, <strong>Terminées</strong>.</li></ul><p>Les filtres sont gardés dans l&#39;adresse de la page.</p><hr><h2 id="liste-des-taches" tabindex="-1">Liste des tâches <a class="header-anchor" href="#liste-des-taches" aria-label="Permalink to &quot;Liste des tâches&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Colonne</th><th>Contenu</th></tr></thead><tbody><tr><td><strong>Statut</strong></td><td>En attente, Planifié, En cours, Terminé, Échoué, Annulé</td></tr><tr><td><strong>Tâche</strong></td><td>type de tâche, compte, et origine : « Règle », « Nettoyage › expéditeur », « Mails › requête » ou « Relance »</td></tr><tr><td><strong>Progression / résultat</strong></td><td>barre de progression en direct, « Terminé · N mails traités », message d&#39;erreur, « Arrêté »…</td></tr><tr><td><strong>Durée</strong></td><td>durée d&#39;exécution</td></tr></tbody></table><p>« En attente » regroupe les tâches qui patientent dans la file et celles qui attendent la fin de leur délai d&#39;annulation (10 s après une suppression, par exemple).</p><p>Le pied indique « N sur M · historique conservé 30 jours » ; <strong>Afficher plus</strong> charge la suite.</p><hr><h2 id="actions-selon-le-statut" tabindex="-1">Actions selon le statut <a class="header-anchor" href="#actions-selon-le-statut" aria-label="Permalink to &quot;Actions selon le statut&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Statut</th><th>Action</th></tr></thead><tbody><tr><td>En attente</td><td><strong>Annuler</strong> : la tâche ne s&#39;exécutera pas</td></tr><tr><td>En cours</td><td><strong>Arrêter</strong>, dans la barre de progression</td></tr><tr><td>Échouée</td><td><strong>Relancer</strong> et <strong>Détails</strong> (date de lancement et message d&#39;erreur)</td></tr><tr><td>Terminée</td><td><strong>Voir</strong> : ouvre la page concernée (Mails, Règles, Nettoyage, Archives…), sinon <strong>Détails</strong></td></tr></tbody></table><p>Une tâche d&#39;import IMAP ne peut pas être relancée d&#39;ici, car le mot de passe n&#39;est pas conservé : « Cette tâche demande des identifiants non conservés : relancez-la depuis sa page. »</p><hr><h2 id="ailleurs-dans-l-application" tabindex="-1">Ailleurs dans l&#39;application <a class="header-anchor" href="#ailleurs-dans-l-application" aria-label="Permalink to &quot;Ailleurs dans l&#39;application&quot;">​</a></h2><p>La progression d&#39;une tâche s&#39;affiche aussi là où elle a été lancée (ligne d&#39;expéditeur dans Nettoyage, en-tête d&#39;Archives, liste de Mails), et la <a href="./overview.html">Vue d&#39;ensemble</a> liste les jobs en cours. À la fin d&#39;une tâche, une <a href="./notifications.html">notification</a> peut être envoyée selon vos préférences.</p>',19)])])}const h=e(n,[["render",o]]);export{p as __pageData,h as default};
